insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m1.q1', 'm1', 'single', 'm1.2', 'Which command stages every changed file for the next commit?', null, '["git push","git add .","git commit","git init"]'::jsonb, 'Staging means choosing what goes into the next snapshot.', '1'::jsonb, '["git push uploads commits to GitHub. It doesn''t stage anything.","Correct: git add . stages every change in the current folder.","git commit saves what is already staged. Staging comes first, with git add.","git init creates a new repository. You only run it once per project."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m1.q2', 'm1', 'single', 'm1.2', 'You edited index.html and ran git commit -m "Update header". Git replies "nothing added to commit". What went wrong?', null, '["The commit message is too short","You didn''t stage the change with git add","You need to push first","index.html is not a valid file name"]'::jsonb, 'Which of the three areas does git commit read from?', '1'::jsonb, '["Git accepts short messages. The message isn''t the problem.","Correct: only staged changes are committed, so run git add index.html first.","Pushing comes after committing. There is nothing to push yet.","index.html is a perfectly valid file name."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m1.q3', 'm1', 'single', 'm1.2', 'What is in the staging area?', null, '["Every file in your project folder","Changes you have chosen to include in the next commit","Commits that are waiting on GitHub","Files Git is ignoring"]'::jsonb, 'Think of it as the box you pack before sealing a snapshot.', '1'::jsonb, '["That''s the working directory. Staging only holds the changes you picked with git add.","Correct: the staging area is the next commit being prepared.","GitHub holds pushed commits. The staging area is on your computer, before any commit.","Ignored files never enter the staging area."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m1.q4', 'm1', 'single', 'm1.3', 'Which commit message is most useful?', null, '["fix","Add About section to portfolio","asdfgh","changes 2"]'::jsonb, 'Good messages say what changed, as a short instruction.', '1'::jsonb, '["Fix what? In a long history this tells you nothing.","Correct: specific and written as an instruction.","Random letters make the history impossible to search.","Numbered vague messages don''t say what changed."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m1.q5', 'm1', 'single', 'm1.3', 'What uniquely identifies a commit?', null, '["Its message","Its hash, like a1b2c3d","The time it was made","The file names it changed"]'::jsonb, 'The projector shows it next to every verified quest.', '1'::jsonb, '["Two commits can have the same message.","Correct: every commit gets a unique hash. The verifier records it as proof of your work.","Two people can commit at the same moment.","Many commits change the same files."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m1.q6', 'm1', 'single', 'm1.4', 'What does git push do?', null, '["Saves a snapshot on your computer","Sends your commits to the remote repository on GitHub","Downloads the latest commits from GitHub","Stages your changes"]'::jsonb, 'Push sends up, pull brings down.', '1'::jsonb, '["That''s git commit.","Correct: push uploads commits to origin, usually GitHub.","That''s git pull.","That''s git add."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m1.q7', 'm1', 'single', 'm1.4', 'You pushed your work, but the workshop verifier says "Repository not found". What''s the most likely cause?', null, '["The repository is private","You used git add . instead of git add index.html","Your commit message has spaces","You pushed too many files"]'::jsonb, 'Who is allowed to see the repository?', '0'::jsonb, '["Correct: the verifier can only read public repositories. Change the visibility in the repository settings.","Both forms stage files. This doesn''t affect whether the repository can be found.","Spaces in messages are normal.","The number of files doesn''t hide a repository."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m1.q8', 'm1', 'order', 'm1.4', 'Put these commands in order to publish a brand-new project (the GitHub remote is already added).', null, '["git push -u origin main","git add .","git init","git commit -m \"First commit\""]'::jsonb, 'Create, stage, save, upload.', '[2,1,3,0]'::jsonb, '["Create the repository (init), stage the files (add), save the snapshot (commit), then upload it (push)."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m1.q9', 'm1', 'single', 'm1.5', 'Which line makes a heading in Markdown?', null, '["**My Portfolio**","# My Portfolio","- My Portfolio","<My Portfolio>"]'::jsonb, 'It''s a single symbol at the start of the line.', '1'::jsonb, '["Double asterisks make bold text.","Correct: # starts a heading; ## makes a smaller one.","A dash starts a bullet-list item.","Angle brackets aren''t Markdown syntax for headings."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m1.q10', 'm1', 'single', 'm1.5', 'Spot the bug in this README. Which line is broken?', '1  # Ana''s Portfolio
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m1.q11', 'm1', 'single', 'm1.6', 'Which prompt will get you the most useful answer?', null, '["git help","Give me git commands","You are a patient Git teacher. I''m on Windows with a folder called portfolio. Give me numbered steps to create a repo, add a README and push it to https://github.com/ana/portfolio, and explain each command.","Do everything for my GitHub, quickly"]'::jsonb, 'Role, task, context, constraints, output format.', '2'::jsonb, '["Too vague: the AI has to guess what you want.","Which commands? For what? Missing task, context and format.","Correct: role, task, context, constraints and output format are all there.","\"Everything\" and \"quickly\" give the AI nothing specific to work with."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
insert into public.quiz_questions (id, module, kind, lesson, prompt, code, options, hint, answer, explanations, active) values ('m1.q12', 'm1', 'single', 'm1.6', 'The AI suggests a command you don''t understand. What should you do?', null, '["Run it straight away","Ask the AI to explain it line by line first","Skip the whole task","Copy it into your README"]'::jsonb, 'You are the pilot; the AI is the co-pilot.', '1'::jsonb, '["Some commands delete or overwrite work. Understand first.","Correct: you stay in control and you learn something.","No need to give up. Ask for an explanation instead.","That doesn''t help you understand or run it safely."]'::jsonb, true) on conflict (id) do update set module = excluded.module, kind = excluded.kind, lesson = excluded.lesson, prompt = excluded.prompt, code = excluded.code, options = excluded.options, hint = excluded.hint, answer = excluded.answer, explanations = excluded.explanations, active = true;
